// components/PlantilirModel.jsx
// A stylized rotating neon crystal using React Three Fiber + Drei

'use client';
import { Canvas } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import { useRef } from 'react';
import * as THREE from 'three';

function Crystal() {
  const mesh = useRef(null);

  return (
    <mesh ref={mesh} rotation={[0.6, 0.6, 0]}>      
      <octahedronGeometry args={[1.2, 0]} />
      <meshStandardMaterial
        color="#7f5cff"
        roughness={0.15}
        metalness={0.85}
        emissive="#5c3bff"
        emissiveIntensity={1.6}
        transparent
        opacity={0.9}
      />
    </mesh>
  );
}

export default function PlantilirModel() {
  return (
    <div className="w-full h-full">
      <Canvas gl={{ antialias: true }} camera={{ position: [0, 0, 4] }}>
        <ambientLight intensity={0.4} />
        <pointLight intensity={1.4} position={[3, 3, 3]} color="#b388ff" />
        <pointLight intensity={1.1} position={[-3, -2, -1]} color="#5f2fff" />
        <Crystal />
        <OrbitControls enableZoom={false} autoRotate autoRotateSpeed={1.5} />
      </Canvas>
    </div>
  );
}


// tailwind.config.js
